export const providerProfilesEleventh:Record<string,ProviderProfile>=Object.fromEntries(rows.map(([name,officialUrl,category,de,en,extraDe,extraEn])=>{
  const c=categories[category];
  const summaryDe=`${de} ${c.contextDe}`,summaryEn=`${en} ${c.contextEn}`;
  return [name,{officialUrl,officialLabel:{de:name==="ESS Solutions"?"Offizielle Herstellerquelle ESS MODERN":"Offizielle Anbieterquelle",en:name==="ESS Solutions"?"Official manufacturer source ESS MODERN":"Official provider source"},
    metaDescription:{de:summaryDe.slice(0,155),en:summaryEn.slice(0,155)},
    summary:{de:summaryDe,en:summaryEn},
    focus:{de:[...extraDe.split(";"),...c.focusDe.split(";")],en:[...extraEn.split(";"),...c.focusEn.split(";")]},
    buyerGroups:{de:c.rolesDe.split(";"),en:c.rolesEn.split(";")},
    ...(name.startsWith("AOC International")?{officialSources:[{url:"https://mmdmonitors.com/",label:{de:"MMD Unternehmensquelle",en:"MMD corporate source"}}]}:{})}];
}));
